<?php require '../includes/core.php';$u=require_subscriber();$plan=plan_data($u);$limit=$plan['limit']??3;$q=db()->prepare('SELECT COUNT(*) FROM tickets WHERE user_id=? AND created_at>=DATE_FORMAT(NOW(),\'%Y-%m-01\')');$q->execute([$u['id']]);$used=(int)$q->fetchColumn();$remaining=$limit===0?null:max(0,$limit-$used);$error='';$subjectPref=trim($_GET['subject']??'');$catPref=trim($_GET['category']??'Software');$descPref=trim($_GET['description']??'');if($_SERVER['REQUEST_METHOD']==='POST'){csrf();$q->execute([$u['id']]);$used=(int)$q->fetchColumn();if($limit!==0 && $used>=$limit)$error='Você atingiu o limite mensal de chamados do seu plano. Faça upgrade para continuar.';else{$subject=trim($_POST['subject']??'');$cat=trim($_POST['category']??'');$desc=trim($_POST['description']??'');if(mb_strlen($subject)<4||mb_strlen($desc)<10||!in_array($cat,['Software','Hardware','Redes','Segurança','Técnico','Financeiro','Dúvidas','Outros'],true))$error='Preencha título, categoria e descrição com pelo menos 10 caracteres.';else{$pdo=db();$s=$pdo->prepare("INSERT INTO tickets(user_id,subject,category,priority,description,status) VALUES(?,?,?,'Média',?,'Aberto')");$s->execute([$u['id'],$subject,$cat,$desc]);$id=(int)$pdo->lastInsertId();notify_admins('Novo chamado #'.$id,$u['name'].' abriu: '.$subject,'admin/ticket.php?id='.$id);notify('Chamado criado!');go('user/ticket.php?id='.$id);}}}layout_start('Novo chamado',$u);?><div class="card" style="max-width:760px;margin:auto"><span class="kicker">NOVO ATENDIMENTO</span><h1>Abrir chamado</h1><p class="muted">Plano <?=h($u['active_plan'])?> · <?= $remaining===null?'Novos chamados ilimitados':$remaining.' chamados disponíveis neste mês' ?></p><?php if($error):?><div class="error"><?=h($error)?></div><?php endif;?><?php if($limit===0||$used<$limit):?><form method="post"><input type="hidden" name="csrf" value="<?=token()?>"><?php fld('subject','Assunto','text',$subjectPref?:'');?><label class="field"><span>Categoria</span><select name="category"><?php foreach(['Software','Hardware','Redes','Segurança','Técnico','Financeiro','Dúvidas','Outros'] as $opt):?><option <?= $catPref===$opt?'selected':'' ?>><?=h($opt)?></option><?php endforeach;?></select></label><label class="field"><span>Descreva o problema</span><textarea name="description" required minlength="10"><?=h($descPref)?></textarea></label><button class="btn">Enviar chamado</button></form><?php else:?><p>Seu limite mensal foi atingido. Você ainda pode acompanhar e responder chamados existentes.</p><a class="btn" href="<?=url('plans.php')?>">Conhecer planos superiores</a><?php endif;?></div><?php layout_end();?>